-- CA-001E owns coordination metadata only. CA-001A-D and product records remain authoritative.
create table public.activation_assignments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,customer_account_id uuid not null,product_family text,journey_id uuid references public.first_value_journeys(id),assigned_operator_id uuid not null references public.profiles(id),assigned_by uuid not null references public.profiles(id),status text not null check(status in('active','completed','cancelled')),reason_code text,assigned_at timestamptz not null,completed_at timestamptz,revision integer not null default 1,foreign key(customer_account_id,tenant_id)references public.customer_accounts(id,tenant_id));create unique index activation_assignment_active_uidx on public.activation_assignments(customer_account_id,coalesce(product_family,''),coalesce(journey_id,'00000000-0000-0000-0000-000000000000'::uuid))where status='active';
create table public.activation_assignment_history(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,assignment_id uuid not null references public.activation_assignments(id),from_operator_id uuid references public.profiles(id),to_operator_id uuid not null references public.profiles(id),actor_id uuid not null references public.profiles(id),reason_code text not null,revision integer not null,correlation_id text not null,occurred_at timestamptz not null,unique(assignment_id,revision));
create table public.activation_internal_notes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,customer_account_id uuid not null,product_family text,journey_id uuid references public.first_value_journeys(id),body text not null check(length(body)between 1 and 4000),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),supersedes_note_id uuid references public.activation_internal_notes(id),foreign key(customer_account_id,tenant_id)references public.customer_accounts(id,tenant_id));
create table public.activation_customer_guidance(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,customer_account_id uuid not null,product_family text,journey_id uuid references public.first_value_journeys(id),guidance_code text not null,customer_safe_message text not null check(length(customer_safe_message)between 1 and 1000),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),supersedes_guidance_id uuid references public.activation_customer_guidance(id),foreign key(customer_account_id,tenant_id)references public.customer_accounts(id,tenant_id));
create table public.activation_escalations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,customer_account_id uuid not null,product_family text,journey_id uuid references public.first_value_journeys(id),blocker_code text not null,responsibility text not null check(responsibility in('customer','internal','system')),status text not null check(status in('open','acknowledged','resolved','cancelled')),created_by uuid not null references public.profiles(id),reason_code text not null,follow_up_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),revision integer not null default 1,foreign key(customer_account_id,tenant_id)references public.customer_accounts(id,tenant_id));
create table public.activation_admin_operations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,customer_account_id uuid not null,actor_id uuid not null references public.profiles(id),action_code text not null,correlation_id text not null,idempotency_key_hash text not null unique,status text not null check(status in('started','completed','failed')),upstream_reference_type text,upstream_reference_id text,stable_failure_code text,created_at timestamptz not null default now(),completed_at timestamptz,foreign key(customer_account_id,tenant_id)references public.customer_accounts(id,tenant_id));
create table public.activation_admin_audit_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,customer_account_id uuid not null,operation_id uuid references public.activation_admin_operations(id),event_type text not null,actor_id uuid not null references public.profiles(id),product_family text,journey_id uuid references public.first_value_journeys(id),outcome text not null,correlation_id text not null,occurred_at timestamptz not null default now(),foreign key(customer_account_id,tenant_id)references public.customer_accounts(id,tenant_id));
create index activation_assignment_queue_idx on public.activation_assignments(tenant_id,status,assigned_operator_id,assigned_at);create index activation_escalation_queue_idx on public.activation_escalations(tenant_id,status,follow_up_at);create index activation_operations_recovery_idx on public.activation_admin_operations(status,created_at);
alter table public.activation_assignments enable row level security;alter table public.activation_assignment_history enable row level security;alter table public.activation_internal_notes enable row level security;alter table public.activation_customer_guidance enable row level security;alter table public.activation_escalations enable row level security;alter table public.activation_admin_operations enable row level security;alter table public.activation_admin_audit_events enable row level security;
create policy "admins read activation assignments"on public.activation_assignments for select to authenticated using(public.is_admin());create policy "admins read assignment history"on public.activation_assignment_history for select to authenticated using(public.is_admin());create policy "admins read activation internal notes"on public.activation_internal_notes for select to authenticated using(public.is_admin());create policy "admins read activation guidance"on public.activation_customer_guidance for select to authenticated using(public.is_admin());create policy "admins read activation escalations"on public.activation_escalations for select to authenticated using(public.is_admin());create policy "admins read activation operations"on public.activation_admin_operations for select to authenticated using(public.is_admin());create policy "admins read activation audit"on public.activation_admin_audit_events for select to authenticated using(public.is_admin());
revoke all on public.activation_assignments,public.activation_assignment_history,public.activation_internal_notes,public.activation_customer_guidance,public.activation_escalations,public.activation_admin_operations,public.activation_admin_audit_events from anon;revoke all on public.activation_assignments,public.activation_assignment_history,public.activation_internal_notes,public.activation_customer_guidance,public.activation_escalations,public.activation_admin_operations,public.activation_admin_audit_events from authenticated;grant select on public.activation_assignments,public.activation_assignment_history,public.activation_internal_notes,public.activation_customer_guidance,public.activation_escalations,public.activation_admin_operations,public.activation_admin_audit_events to authenticated;
